import { useState, useEffect } from 'react';
export function useLocalStorage<T>(key: string, initialValue: T) {
  const [value, setValue] = useState<T>(() => {
    const stored = localStorage.getItem(key);
    return stored ? JSON.parse(stored) : initialValue;
  });
  useEffect(() => {
    localStorage.setItem(key, JSON.stringify(value));
  }, [key, value]);
  return [value, setValue] as const;
}

import express, { Request, Response } from 'express';
import multer from 'multer';
import pdfParse from 'pdf-parse';

const upload = multer({ storage: multer.memoryStorage() });
const router = express.Router();

interface MatchResult {
  score: number;
  matchedKeywords: string[];
  missingKeywords: string[];
  totalKeywordsChecked: number;
}

router.post('/scan', upload.single('resume'), async (req: Request, res: Response): Promise<void> => {
  try {
    if (!req.file) {
      res.status(400).json({ error: 'No resume PDF file provided' });
      return;
    }

    const jobDescription = req.body.jobDescription as string;
    if (!jobDescription) {
      res.status(400).json({ error: 'Job description is required' });
      return;
    }

    // Parse PDF buffer
    const pdfData = await pdfParse(req.file.buffer);
    const resumeText = pdfData.text.toLowerCase();

    // Extract unique keywords from job description (alphanumeric tokens > 3 chars)
    const rawTokens = jobDescription.toLowerCase().match(/\b[a-z]{4,}\b/g) || [];
    const stopWords = new Set(['with', 'this', 'that', 'from', 'your', 'have', 'will', 'pref', 'and', 'the', 'for']);
    const keywords = Array.from(new Set(rawTokens.filter(token => !stopWords.has(token))));

    const matchedKeywords: string[] = [];
    const missingKeywords: string[] = [];

    keywords.forEach(keyword => {
      if (resumeText.includes(keyword)) {
        matchedKeywords.push(keyword);
      } else {
        missingKeywords.push(keyword);
      }
    });

    const score = keywords.length > 0 
      ? Math.round((matchedKeywords.length / keywords.length) * 100) 
      : 0;

    const result: MatchResult = {
      score,
      matchedKeywords,
      missingKeywords,
      totalKeywordsChecked: keywords.length
    };

    res.status(200).json(result);
  } catch (error) {
    console.error('Scan error:', error);
    res.status(500).json({ error: 'Failed to parse resume and calculate match score' });
  }
});

export default router;

import React, { useState } from 'react';
import axios from 'axios';

interface ScanResult {
  score: number;
  matchedKeywords: string[];
  missingKeywords: string[];
  totalKeywordsChecked: number;
}

export const TailwindScoreDashboard: React.FC = () => {
  const [file, setFile] = useState<File | null>(null);
  const [jobDescription, setJobDescription] = useState<string>('');
  const [loading, setLoading] = useState<boolean>(false);
  const [result, setResult] = useState<ScanResult | null>(null);

  const handleScan = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!file || !jobDescription) return;

    const formData = new FormData();
    formData.append('resume', file);
    formData.append('jobDescription', jobDescription);

    setLoading(true);
    try {
      const response = await axios.post<ScanResult>('/api/scan', formData, {
        headers: { 'Content-Type': 'multipart/form-data' },
      });
      setResult(response.data);
    } catch (err) {
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="max-w-4xl mx-auto p-6 bg-slate-900 text-slate-100 min-h-screen font-sans">
      <header className="mb-8 text-center">
        <h1 className="text-3xl font-extrabold tracking-tight text-indigo-400">AI Resume Keyword Scanner</h1>
        <p className="text-slate-400 mt-2">Optimize your resume against target job descriptions instantly.</p>
      </header>

      <form onSubmit={handleScan} className="grid grid-cols-1 md:grid-cols-2 gap-6 bg-slate-800 p-6 rounded-xl border border-slate-700 shadow-xl">
        <div>
          <label className="block text-sm font-medium text-slate-300 mb-2">Upload Resume (PDF)</label>
          <input 
            type="file" 
            accept=".pdf"
            onChange={(e) => setFile(e.target.files?.[0] || null)}
            className="w-full text-sm text-slate-400 file:mr-4 file:py-2 file:px-4 file:rounded-lg file:border-0 file:text-sm file:font-semibold file:bg-indigo-600 file:text-white hover:file:bg-indigo-500 cursor-pointer"
          />
        </div>
        <div>
          <label className="block text-sm font-medium text-slate-300 mb-2">Job Description</label>
          <textarea 
            rows={4}
            value={jobDescription}
            onChange={(e) => setJobDescription(e.target.value)}
            placeholder="Paste job description here..."
            className="w-full p-3 rounded-lg bg-slate-900 border border-slate-700 text-slate-200 focus:outline-none focus:ring-2 focus:ring-indigo-500"
          />
        </div>
        <div className="md:col-span-2">
          <button 
            type="submit"
            disabled={loading || !file || !jobDescription}
            className="w-full py-3 px-4 bg-indigo-600 hover:bg-indigo-500 disabled:bg-slate-700 text-white font-semibold rounded-lg shadow-md transition-all duration-200"
          >
            {loading ? 'Analyzing Resume...' : 'Scan & Calculate Match Score'}
          </button>
        </div>
      </form>

      {result && (
        <div className="mt-8 grid grid-cols-1 md:grid-cols-3 gap-6">
          <div className="bg-slate-800 p-6 rounded-xl border border-slate-700 flex flex-col items-center justify-center text-center">
            <div className="relative w-32 h-32 flex items-center justify-center rounded-full bg-slate-900 border-4 border-indigo-500 shadow-inner">
              <span className="text-4xl font-bold text-white">{result.score}%</span>
            </div>
            <span className="mt-4 text-sm font-medium text-slate-300">Overall Match Score</span>
          </div>

          <div className="bg-slate-800 p-6 rounded-xl border border-slate-700 md:col-span-2">
            <h3 className="text-lg font-semibold text-emerald-400 mb-3">Matched Keywords ({result.matchedKeywords.length})</h3>
            <div className="flex flex-wrap gap-2 mb-6">
              {result.matchedKeywords.map((kw, i) => (
                <span key={i} className="px-3 py-1 bg-emerald-950 text-emerald-300 border border-emerald-800 text-xs rounded-full font-medium">
                  {kw}
                </span>
              ))}
            </div>

            <h3 className="text-lg font-semibold text-rose-400 mb-3">Missing Keywords ({result.missingKeywords.length})</h3>
            <div className="flex flex-wrap gap-2">
              {result.missingKeywords.map((kw, i) => (
                <span key={i} className="px-3 py-1 bg-rose-950 text-rose-300 border border-rose-800 text-xs rounded-full font-medium">
                  {kw}
                </span>
              ))}
            </div>
          </div>
        </div>
      )}
    </div>
  );
};
